protected void new(IdentifierName _className, IdentifierName _methodName, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    if(_className == '' || _methodName == '')
    {
        throw Error('Empty parameters');
    }

    super(_className, _methodName, _executionMode);
    this.parmDialogCaption("@NDX:NDXRICO_ImportReqDocTransfer");
    this.parmRegisterCallbackForReliableAsyncCall(true);
}

